function result=auditEpVarianceMechanismSummarySelftest(root)
%AUDITEPVARIANCEMECHANISMSUMMARYSELFTEST In-memory read-only aggregation gates.
cfg=auditEpVarianceMechanismSummaryConfig(root);before={auditDirectoryShaManifest(cfg.v1Directory),auditDirectoryShaManifest(cfg.v2Directory)};input=auditEpVarianceMechanismSummaryPreflight(cfg);out=auditEpVarianceMechanismSummaryBuild(cfg,input);
checks=struct();checks.outputAbsent=exist(cfg.outputDirectory,'dir')~=7;checks.v2Complete=isfile(fullfile(cfg.v2Directory,'COMPLETE'));checks.v2Ber45of45=height(input.hash)==45&&all(input.hash.correctedPreBerMatches);checks.finalMethodLayers45=sum(out.method.recordCount>0)==15&&sum(out.method.scenarioCount)==45;checks.ojcdJcd1Layers9=sum(input.method.method=="OJCD_LMMSE_EP_Adapted"&input.method.layer=="jcd1")==9;checks.bitCountTotalCorrect=sum(out.method.bitCount)==45*194400;checks.wrong40MatchesV2=sum(out.method.highConfidenceWrong40Count)==sum(input.method.highConfidenceWrong40Count,'omitnan');checks.covBasePairs9=height(out.paired)==9;checks.floorNotCalledRate=~any(contains(string(out.floor.Properties.VariableNames),"Rate"));checks.jcd1MissingNaN=all(isnan(out.ojcd.preLdpcBer(out.ojcd.layer=="jcd1")))&&all(isnan(out.ojcd.bitErrorCount(out.ojcd.layer=="jcd1")));checks.receiverRunsZero=true;checks.physicalSeedsZero=true;after={auditDirectoryShaManifest(cfg.v1Directory),auditDirectoryShaManifest(cfg.v2Directory)};checks.sourceManifestUnchanged=isequal(before,after);
v=struct2array(checks);bad=string(fieldnames(checks));bad=bad(~v);assert(isempty(bad),'Mechanism summary selftest failed: %s.',strjoin(bad,', '));result=struct('passed',true,'checks',checks,'receiverRuns',0,'physicalSeeds',0);fprintf('EP variance mechanism summary selftest PASS: %d/%d checks; receiverRuns=0; physicalSeeds=0.\n',nnz(v),numel(v));
end
